<?php
/** Distribution denominator is loaded NVD records only, never the entire KEV catalog. */
defined('ABSPATH') || exit;
$coverage=cyberdat_nvd_coverage();$counts=$coverage['counts'];$colors=['Critical'=>'#ff8e9b','High'=>'#f5c76a','Medium'=>'#68cfff','Low'=>'#70f3cb','Unrated / Unclassified'=>'#7d91a4'];
$stops=[];$cursor=0;
foreach($counts as $label=>$value){$end=$cursor+($coverage['loaded']?100*$value/$coverage['loaded']:0);$stops[]=sprintf('%s %.5F%% %.5F%%',$colors[$label],$cursor,$end);$cursor=$end;}
$background=$coverage['loaded']?'conic-gradient('.implode(',',$stops).')':'var(--cd-border)';
?>
<div class="severity-panel" data-nvd-loaded="<?php echo esc_attr($coverage['loaded']); ?>"><div class="panel-heading"><h3><?php esc_html_e('Severity distribution','cyberdat'); ?></h3><span><?php echo esc_html($coverage['snapshots']?__('NVD SNAPSHOT · NOT LIVE','cyberdat'):__('CACHED NVD ASSESSMENTS','cyberdat')); ?></span></div><div class="severity-chart"><div class="severity-ring" style="background:<?php echo esc_attr($background); ?>" role="img" aria-label="<?php echo esc_attr(implode('; ',array_map(static fn($label,$value)=>$label.': '.$value,array_keys($counts),array_values($counts)))); ?>"><span><strong><?php echo esc_html(number_format_i18n($coverage['loaded'])); ?></strong><small>LOADED</small></span></div><ul class="severity-legend"><?php foreach($counts as $label=>$value): ?><li><span class="legend-dot" style="background:<?php echo esc_attr($colors[$label]); ?>"></span><?php echo esc_html($label); ?> <strong><?php echo esc_html($value); ?></strong></li><?php endforeach; ?></ul></div><p class="chart-caption"><?php echo esc_html(sprintf(/* translators: 1: Loaded NVD records, 2: KEV catalog total. */__('CVSS coverage: %1$d of %2$d KEV entries.','cyberdat'),$coverage['loaded'],$coverage['total'])); ?> <?php esc_html_e('Partial coverage; distribution includes loaded NVD records only. Severity is not proof of exploitation.','cyberdat'); ?> <?php echo esc_html(sprintf(/* translators: %d: Number of stale or fixed-snapshot NVD records. */__('Stale/snapshot records: %d.','cyberdat'),$coverage['stale'])); ?></p></div>
